SELECT *
FROM t_oa_device
WHERE device_name = #{deviceName}
AND deleted_flag = #{deletedFlag}

    AND device_id != #{excludeDeviceId}

SELECT *
FROM t_oa_device

    deleted_flag = #{queryForm.deletedFlag}


        AND station_id = #{queryForm.stationId}



        AND (INSTR(device_name,#{queryForm.keywords}) OR INSTR(station_name,#{queryForm.keywords}) OR
        INSTR(serial_number,#{queryForm.keywords}) OR INSTR(dtu_number,#{queryForm.keywords}) OR INSTR(
        station_id, #{queryForm.keywords}
        ))


        AND DATE_FORMAT(create_time, '%Y-%m-%d') >= #{queryForm.startTime}


        AND DATE_FORMAT(create_time, '%Y-%m-%d') <= #{queryForm.endTime}


        AND disabled_flag = #{queryForm.disabledFlag}

        SELECT t_oa_device.*
        FROM t_oa_device

            deleted_flag = #{queryForm.deletedFlag}
--         这个部分可以增加想要查询的 ’关键字‘

                AND (INSTR(device_name,#{queryForm.keywords}) OR INSTR(station_name,#{queryForm.keywords}) OR
                INSTR(serial_number,#{queryForm.keywords}) OR INSTR(dtu_number,#{queryForm.keywords}) OR INSTR(
                station_id, #{queryForm.keywords}
                ))


                AND DATE_FORMAT(create_time, '%Y-%m-%d') >= #{queryForm.startTime}


                AND DATE_FORMAT(create_time, '%Y-%m-%d') <= #{queryForm.endTime}


                AND disabled_flag = #{queryForm.disabledFlag}



            ORDER BY device_id DESC

SELECT t_oa_enterprise.*
FROM t_oa_enterprise

    deleted_flag = #{queryForm.deletedFlag}

        AND (INSTR(enterprise_name,#{queryForm.keywords}) OR INSTR(contact,#{queryForm.keywords}) OR
        INSTR(contact_phone,#{queryForm.keywords}) OR INSTR(create_user_name,#{queryForm.keywords}))


        AND DATE_FORMAT(create_time, '%Y-%m-%d') >= #{queryForm.startTime}


        AND DATE_FORMAT(create_time, '%Y-%m-%d') <= #{queryForm.endTime}


        AND disabled_flag = #{queryForm.disabledFlag}



    ORDER BY create_time DESC

SELECT enterprise_id, enterprise_name
FROM t_oa_enterprise
WHERE disabled_flag = #{disabledFlag}
AND deleted_flag = #{deletedFlag}

    AND type = #{type}

SELECT oe.*
FROM t_oa_device oe
WHERE oe.device_id = #{deviceId} AND oe.deleted_flag = #{deletedFlag}
